#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_LINE   0x800
#define MAX_TOKEN  0x800

static void url_decode(const char *src, char *dst)
{
    while (*src) {
        if (*src == '+') {
            *dst++ = ' ';
            src++;
        } else if (*src == '%' && isxdigit((unsigned char)src[1]) && isxdigit((unsigned char)src[2])) {
            char hex[3] = { src[1], src[2], '\0' };
            *dst++ = (char)strtol(hex, NULL, 16);
            src += 3;
        } else {
            *dst++ = *src++;
        }
    }
    *dst = '\0';
}

int main(void)
{
    static char line[MAX_LINE];
    static char key[MAX_TOKEN];
    static char val[MAX_TOKEN];

    if (fgets(line, sizeof(line), stdin) == NULL) {
        puts("NO_INPUT");
        return 0;
    }

    size_t len = strlen(line);
    while (len && (line[len-1] == '\n' || line[len-1] == '\r')) {
        line[--len] = '\0';
    }

    char *pair = line;
    while (*pair) {
        char *next_amp = strchr(pair, '&');
        if (next_amp) *next_amp = '\0';

        char *eq = strchr(pair, '=');
        if (eq) {
            *eq = '\0';
            url_decode(pair, key);
            url_decode(eq + 1, val);
        } else {
            url_decode(pair, key);
            val[0] = '\0';
        }

        printf("%s=%s\n", key, val);

        if (next_amp) {
            pair = next_amp + 1;
        } else {
            break;
        }
    }
    return 0;
}
